async function performGroupSend(args) {
  const agents = await listAgents();
  const { existing, memberIds, bots, sameSet } = resolveMessageGroup(args, agents);
  const message = args.message?.trim() ?? "";
  const name = args.groupName?.trim() ?? existing?.name ?? "";
  if (!message)
    throw new IntegrationError("not_found", "What should I send?");
  if (memberIds.length < (existing ? 1 : 2))
    throw new IntegrationError("not_found", existing ? "Keep at least one bot in the group." : "Choose at least two bots for a new group.");
  let target = existing;
  const savedName = name || memberIds.map((id) => bots.find((a) => a.id === id).name).join(" + ");
  if (target) {
    if (!sameSet(target.memberIds ?? [], memberIds))
      await setGroupMembers(target.id, memberIds);
    if (target.name !== savedName)
      await renameGroup(target, savedName);
  } else {
    target = await createGroup(savedName, memberIds);
    if (!target?.id)
      throw new IntegrationError("upstream", "The group was not created.");
  }
  await sendPrompt(target.id, message);
  return groupReceipt(agents, { id: target.id, name: savedName, members: memberIds }, message);
}
